            .w(SIDEBAR_WIDTH)
            .h_full()
            .py_2()
            .border_r_1()
            .border_color(theme.border)
            .children(Section::ALL.into_iter().map(|section| {
                let is_picked = section == picked;
                div()
                    .id(SharedString::from(format!(
                        "settings-section-{}",
                        section.key()
