                    .when(!is_picked, |row| {
                        row.text_color(theme.muted_foreground)
                            .hover(|row| row.bg(theme.list_hover))
                    })
                    .cursor_pointer()
                    .child(section.label())
                    .on_click(cx.listener(move |this, _, _, cx| this.pick(section, cx)))
            }))
    }
