            .into_iter()
            .map(|input| {
                cx.subscribe(input, |this, _, event: &InputEvent, cx| {
                    if matches!(event, InputEvent::Change) {
                        this.error = None;
                        cx.notify();
                    }
                })
            })
            .collect();
        let browse_focus = cx.focus_handle();
        // The folder's Browse button has focus as the form opens.
        browse_focus.focus(window, cx);
        Self {
